coding.solution:
def csv_reads(rows, threads, loops, recycle, stop_thread):
    out = {t: [] for t in range(1, threads + 1)}
    stopped = set()
    pos = 0
    for _ in range(loops):
        for t in range(1, threads + 1):
            if t in stopped:
                continue
            if pos >= len(rows):
                if recycle:
                    pos = 0
                elif stop_thread:
                    stopped.add(t)
                    continue
                else:
                    out[t].append('<EOF>')
                    continue
            out[t].append(rows[pos])
            pos += 1
    return out

