def split_rows(rows, n):
    if n < 1 or n > len(rows):
        raise ValueError('bad number of generators')
    size, extra = divmod(len(rows), n)
    chunks, start = [], 0
    for i in range(n):
        end = start + size + (1 if i < extra else 0)
        chunks.append(rows[start:end])
        start = end
    return chunks

